// Código generado por el agente
const code = $fromAI('code', 'Código JavaScript a ejecutar. Debe terminar con return.');
const input_data = $fromAI('input_data', 'Datos de entrada como string JSON (opcional)', 'string');

let inputParsed = {};
try { inputParsed = JSON.parse(input_data || '{}'); } catch(e) {}

const fn = new Function('data', code);
const result = fn(inputParsed);

return [{ json: { result: JSON.stringify(result), success: true } }];
